CREATE TABLE truss.action_family_registration (family_registration_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, installation_id uuid NOT NULL REFERENCES truss.catalog_runtime_installation (installation_id), store_control_id bigint NOT NULL REFERENCES truss.action_store_registration (control_id), store_identity bytea NOT NULL CHECK (octet_length(store_identity) BETWEEN 1 AND 4096), family_identity bytea NOT NULL CHECK (octet_length(family_identity) BETWEEN 1 AND 4096), original_action_pin bytea NOT NULL CHECK (octet_length(original_action_pin) BETWEEN 1 AND 1048576), original_model_artifact bytea NOT NULL CHECK (octet_length(original_model_artifact) BETWEEN 1 AND 4194304), original_preparation_artifact bytea NOT NULL CHECK (octet_length(original_preparation_artifact) BETWEEN 1 AND 4194304), declared_roles bytea[] NOT NULL CHECK (cardinality(declared_roles) BETWEEN 1 AND 64 AND array_ndims(declared_roles) = 1 AND array_lower(declared_roles, 1) = 1 AND array_position(declared_roles, NULL) IS NULL), person_required boolean NOT NULL CHECK (person_required), profile_id text NOT NULL CHECK (profile_id = 'umf.actions.roles'), profile_version text NOT NULL CHECK (profile_version = '1')); CREATE INDEX action_family_registration_route ON truss.action_family_registration USING btree (sha256(store_identity), sha256(family_identity)); CREATE TRIGGER action_family_registration_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON truss.action_family_registration EXECUTE FUNCTION truss.catalog_immutable(); ALTER TABLE truss.action_family_registration ENABLE ALWAYS TRIGGER action_family_registration_immutable; CREATE TABLE truss.action_role_binding (binding_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, family_registration_id bigint NOT NULL REFERENCES truss.action_family_registration (family_registration_id), installation_id uuid NOT NULL REFERENCES truss.catalog_runtime_installation (installation_id), store_identity bytea NOT NULL CHECK (octet_length(store_identity) BETWEEN 1 AND 4096), family_identity bytea NOT NULL CHECK (octet_length(family_identity) BETWEEN 1 AND 4096), role_identity bytea NOT NULL CHECK (octet_length(role_identity) BETWEEN 1 AND 2048), native_role_oid oid NOT NULL, original_action_pin bytea NOT NULL CHECK (octet_length(original_action_pin) BETWEEN 1 AND 1048576), profile_id text NOT NULL CHECK (profile_id = 'umf.actions.roles'), profile_version text NOT NULL CHECK (profile_version = '1')); CREATE INDEX action_role_binding_route ON truss.action_role_binding USING btree (sha256(family_identity), sha256(role_identity)); REVOKE ALL ON truss.action_family_registration, truss.action_role_binding FROM public; REVOKE ALL ON SEQUENCE truss.action_family_registration_family_registration_id_seq, truss.action_role_binding_binding_id_seq FROM public; REVOKE ALL ON TYPE truss.action_family_registration, truss.action_role_binding FROM public